from collections import defaultdict, deque

def max_reachable_pairs(n, m, connections):
    graph = defaultdict(list)
    for a, b in connections:
        graph[a].append(b)
        graph[b].append(a)

    max_reachable = 0
    for u in range(1, n + 1):
        count_u = 1
        queue = deque([u])
        visited = set([u])

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    count_u += 1
                    queue.append(neighbor)

        count_u += len(list(graph[u]))

        for neighbor in graph[u]:
            if neighbor not in graph[u]:
                for other in graph[neighbor]:
                    if other in graph[u]:
                        count_u -= 1
        max_reachable = max(max_reachable, count_u)

    return max_reachable

