def max_connected_component(n, k, grid):
    def expand(grid, x, y):
        dx = [0, 1, 0, -1]
        dy = [1, 0, -1, 0]
        queue = [(x, y, 0)]
        visited = set()

        while queue:
            x, y, distance = queue.pop(0)
            for i in range(4):
                new_x, new_y = x + dx[i], y + dy[i]
                if 0 <= new_x < n and 0 <= new_y < n and (new_x, new_y) not in visited and grid[new_x][new_y] == '.':
                    visited.add((new_x, new_y))
                    queue.append((new_x, new_y, distance + 1))

        return max(distance for _, _, distance in queue)

    if k > n:
        return n**2

    visited_componsition = set()
    pieces = []
    for i in range(n):
        row = (set((i, j) for j in range(n)) - visited_componsition).pop()
        pieces.append(expand(grid, row, row))

    return max(p * pieces[0] // k for p in range(n // k + 1))
