    resources_gained = sum(resource_diffs)
    color_diff = sum([1 if card.color == 'R' else -1 for card in cards])
    total_cards = sum([card.redundant for card in cards])

    if total_cards > 0:
        return -1
    elif color_diff < 0 and resources_gained > 0:
        return count_moves(color_diff, resources_gained)
    else:
        return min(count_moves(color_diff, resources_gained), count_moves(color_diff, resources_gained + 1))

def count_moves(color_diff, initial_resources):
