import random

def generate_test_cases(N, M):
    grid = []
    marked_cells = set()

    for _ in range(N):
        row = []
        for _ in range(N):
            row.append(-1000000000)
        grid.append(row)
        for _ in range(M):
            while True:
                x, y = random.randint(1, N), random.randint(1, N)
                if (x, y) not in marked_cells:
                    marked_cells.add((x, y))
                    break
            grid[-1][y-1] = random.randint(-1000000000, 1000000000)

    return grid

def find_max_weight_paths(grid, marked_cells):
    paths = []
    min_weight = float('inf')

    def dfs(x, y, path, total_weight):
        nonlocal min_weight
        if len(path) == 2 * M:
            nonlocal paths
            path.extend([x, y])
            weight = 0
            for i in range(0, len(path) - 1, 2):
                weight += grid[path[i]][path[i + 1]]
            if weight < min_weight:
                min_weight = weight
                paths.clear()
                paths.append(path)
            elif weight == min_weight:
                paths.append(path)
            return

        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in marked_cells:
                path.append(nx)
                path.append(ny)
                dfs(nx, ny, path, total_weight - grid[nx][ny])
                path.pop()
                path.pop()

    for i in range(2*M-1, -1, -1):
        dfs(i, i, [i//2-i%2], grid[i//2][i%2])

    return [[x, v] for path in paths for (x, v) in path]

