import sys

def max_permutation_solution(A):
    # Sort the negative and positive values separately
    A_pos, A_neg = [], []
    for num in A:
        if num >= 0:
            A_pos.append(num)
        else:
            A_neg.append(num)

    # Determine the direction: either positive or negative
    # If there are more positive values than the count of elements, use positive/negative
    if len(A_pos) > len(A_neg):
        used_best_N = max(len(A_pos), len(A_neg))
        if len(A_pos) > 0:
            A_neg = A_pos
        else:
            A_neg = A
        A_pos = A_neg[:used_best_N]

    # Reverse the list of negative values
    A_neg = A_neg[::-1]

    # Create the permutation
    B = []
    for i in range(len(A)):
        if using_pos[i % len(A_pos)]:
            B.append(A_pos[i % len(A_pos)])
        if using_neg[i % len(A_neg)]:
            B.append(A_neg[i % len(A_neg)])

    return B

