from typing import List

class SegmentTree:
    def __init__(self, array):
        self.tag = 0
        self.build(0, len(array) - 1, array)

    def build(self, node: int, end: int, array: List[int]):
        if end - node != 1:
            self.tag += 1
            mid = (node + end) // 2
            self.build(node * 2 + 0, mid, array)
            self.build(node * 2 + 1, end, array)
        else:
            self.array = array

    def update(self, node: int, diff: int):
        if self.tag > 0:
            return
        self.array[node] += diff
        self.tag += 1

    def query(self, node: int, left: int, leftEnd: int):
        if self.tag > 0:
            return
        if left > right or leftEnd < right:
            return 0
        if left == leftEnd:
            return self.array[node] + self.tag * (1 - (self.tag - 1) // 2)
        return self.array[node] + self.tag * (1 - (self.tag - 1) // 2) + (
            self.query(3 * node + 1, left, leftEnd) + 
            self.query(3 * node + 2, leftEnd + 1, right)
        )

class Solution:
    def treeDist(self, tree: List[int], n: int) -> int:
        seg_tree = SegmentTree([0])
        for x, y in tree:
            seg_tree.update(0, 1)
            seg_tree.update(1, 1)
        ans = seg_tree.query(0, 0, n - 1)
        # calculate the sum of all segments of seg_tree inclusive
        for _ in range(len(seg_tree.array)):
            seg_tree.tag = 0
            seg_tree.build(0, len(seg_tree.array) - 1, seg_tree.array)
            seg_tree.update(seg_tree.tag, -1)
            seg_tree.update(seg_tree.tag, -1)
        return ans
