import math

def is_doofish_matrix(N):
    """Check if there exists a Doofish Matrix of order N."""
    # The diagonal elements must be the sum of their column index (1 to 2N-1) minus 1.
    return N * (N - 1) // 2 < (2 * N - 1)

def print_doofish_matrix(N):
    """Print one valid Doofish Matrix of order N."""
    for _ in range(N):
        print("Hooray", end="")
        print(" ".join(str(i+1) for i in range(0, N)))
        print()

def solution(T):
