def construct_doofish_matrix(N, matrix):
    for i in range(1, N+1):
        for j in range(i, 2*N):
            if (2*(j - i + 2*N+1)**2) % i == 0:
                matrix[i-1][j-(2*N+1)+1] = j
    return matrix

