def largest_component_size(n, k, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    cell_groups = defaultdict(set)

    for r in range(n):
        for c in range(n):
            if grid[r][c] == '.':
                for dr, dc in directions:
                    if 0 <= r + dr < n and 0 <= c + dc < n and grid[r + dr][c + dc] == '.':
                        cell_groups[(r, c)].update([(r + dr, c + dc)])

    max_size = 0
    for group in cell_groups.values():
        if len(group) >= k * k:
            connected_cells = k * k
            for r1, c1 in group:
                for dr, dc in directions:
                    new_r, new_c = r1 + dr, c1 + dc
                    if 0 <= new_r < n and 0 <= new_c < n:
                        connected_cells += len(list(filter(lambda x: grid[new_r][x] == '.',
                                                           group)[k-1:]))
            max_size = max(max_size, connected_cells)

    return max_size

