def max_connected_component(n, k, grid):
    def dfs(i, j, changed):
        if 0 <= i < n and 0 <= j < n and not grid[i][j] and not changed[i][j]:
            grid[i][j] = 'L'  # Used to mark cells already processed
            changed[i][j] = True
            dfs(i + 1, j, changed)
            dfs(i - 1, j, changed)
            dfs(i, j + 1, changed)
            dfs(i, j - 1, changed)

    borders = [[n, n, 1]]

    for _ in range(k):
        max_row = 0
        for i in range(n):
            row = 0
            for j in range(n):
                if grid[i][j] == 'X':
                    row += 1
                else:
                    if j > max_row:
                        max_row = j
                    if row > borders[-1][1]:
                        borders.append([max_row, row, 1])

        for i, j, size in borders:
            if size == k - 1:
                grid[i][j] = 'X'
            borders.remove([i, j, size])
        borders.append([n, n, 1])

    return sum(1 for i in range(n) for j in range(n) if grid[i][j] == 'L' and not changed[i][j])
