    for w in range(width):
        for r in prev_row:
            dp[r - 1] = f(dp[r - 1] + dp[r])
        for r in prev_row:
            val = 2 * dp[r + 1]
            dp[r + 1] = f(val)
            dp[r] = f(dp[r] + val)
        c -= 1

    res = 0
    for a, b in dp.items():
        if a == w:
            res = f(res + b)
        else:
            res = f(res + f(b))
    return f(res % MOD)

