from collections import defaultdict

def find_superset(query_a, query_b):
    if not query_a or not query_b:
        return False, 0
    if query_a == query_b:
        return True, len(query_a)
    if query_a is query_b:
        return True, len(query_a)
    x, y = len(query_a), len(query_a[0])
    square = defaultdict(int)
    for i, row in enumerate(query_a):
        for j, val in enumerate(row):
            square[x + y - i - j] += query_b[x + y - i - j] if 0 <= x + y - i - j < y else 0
    for i, row in enumerate(query_b):
        for j, val in enumerate(row):
            square[x - i - j] += query_a[x - i - j] if 0 <= x - i - j < x else 0
    return all(square[v] > 0 for v in square)

def process_query(lmt, query):
    rect_a = [[0] * i for i in range(1, lmt + 1)]
    for i, (a, b) in enumerate(zip(lmt.reverse(), query)):
        rect_a[a][b-1] = 1
    max_square = 0
    for x in range(len(rect_a)):
        max_square = max(max_square, count_ones(rect_a[x]))
    for y in range(1, len(rect_a[0])):
        max_square = max(max_square, count_ones([list(row)[y:] for row in rect_a]))
    for y in range(len(rect_a[0]) - 2, -1, -1):
        for x in range(len(rect_a)):
            if rect_a[x][y]:
                rect_a[x].append(0)
            else:
                rect_a[x].append(count_ones(rect_a[x][-1])[1])
            max_square = max(max_square, count_ones(rect_a[x][y + 1:]))
    for x, row in enumerate(rect_a):
        for y in range(len(rect_a[0]) - 2, -1, -1):
            if rect_a[x][y]:
                rect_a[x].append(0)
            else:
                rect_a[x].append(count_ones(row[y + 1:])[1])
            max_square = max(max_square, count_ones(rect_a[x][y + 1:]))
    return max(1, max_square)

def count_ones(arr):
