from collections import defaultdict

def find_max_permutation(A):
    n = len(A)

    # Build the adjacency list
    graph = defaultdict(list)
    for i in range(n - 1):
        for j in range(i + 1, n):
            a, b = A[i], A[j]
            if abs(i - j) - 1 > 0:
                before = i - (abs(i - j) - 1)
                after = j + 1 + (abs(i - j) - 1)
                graph[before].append(after)
                graph[after].append(before)

    visited = [False] * n
    def dfs(start, depth):
        if start == -1:
            return
        visited[start] = True
        for next_node in graph[start]:
            if not visited[next_node]:
                dfs(next_node, depth + 1)
        visited[start] = False

    max_depth = 0
    roots = []
    for i in range(n):
        if not visited[i]:
            roots.append(i)
            dfs(i, 1)

    max_length = 0
    max_pos = -1
    for i in roots:
        if max_depth < len(graph[i]):
            max_depth = len(graph[i])
            max_pos = i

    b = [i + 1 for i, _ in enumerate(A)]
    for i in range(n):
        for next_node in graph[max_pos]:
            b[next_node] = max_pos

    return b

