import sys

def max_reachable_pairs(n, m):
    # Initialize a graph with all connections as bidirectional
    edges = {i: [] for i in range(1, n + 1)}
    for _ in range(m):
        u, v = map(int, input().split())
        edges[u].append(v)
        edges[v].append(u)

    # Initialize a function to determine if there's a path from i to j in the current direction
    def can_reach(i, j, direction):
        queue = [(i, (None, j, i))]
        visited = {i}
        while queue:
            node, (start, mid, dest) = queue.pop(0)
            if mid == dest:
                return True
            for neighbor in edges[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, (node, mid, dest)))
        return False

    def update_digraph():
        # Dijkstra's algorithm to explore paths and update digraph
        arrived = [False] * (n + 1)
        distance = [sys.maxsize] * (n + 1)
        distance[1] = 0
        queue = [(distance[0], 1)]
        while queue:
            current_dist, current = queue.pop(0)
            if current_dist > distance[current]:
                continue
            for neighbor in edges[current]:
                new_dist = current_dist + edges[current][neighbor]
                if new_dist < distance[neighbor]:
                    distance[neighbor] = new_dist
                    if can_reach(neighbor, 1, 'b'):
                        queue.append((new_dist, neighbor))
        arrived[current] = True

    total_pairs = 0
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            total_pairs += edges[i].count(j)
            if can_reach(i, j, 'b'):
                total_pairs += edges[j].count(i)

    return total_pairs

