from collections import defaultdict

def tournament_winner(matches):
    """Simulate the tournament and calculate the number of possible winners."""
    sport_to_set = defaultdict(set)
    valid_sport = set()
    for match in matches:
        if match[2] not in valid_sport:
            valid_sport.add(match[2])
        sport_to_set[match[2]].add(match[0])
        sport_to_set[match[2]].add(match[1])

    results = defaultdict(int)
    for sport in valid_sport:
        winner = sport_to_set[sport].pop()
        results[sport] += 1
        if len(sport_to_set[sport]) == 0:
            result_set = {winner}
            for other_sport in valid_sport:
                if sport == other_sport:
                    continue
                for m in results.keys():
                    m_to_add = m in sport_to_set[other_sport]
                    if m_to_add:
                        result_set.add(sport_to_set[m].pop())
            valid_sport = result_set
    return len(valid_sport)

