from collections import defaultdict

def max_reachable_pairs(junctions, streets):
    level, connections = [0] * (junctions + 1), [[] for _ in range(junctions + 1)]

    # Initialize Level and Connections
    for u, v in streets:
        level[u] += 1
        level[v] += 1
        connections[u] += [v]
        connections[v] += [u]

    queue = []
    for junction, level in enumerate(level):
        if level == 1:
            queue.append(junction)

    reachable_junctions = {}
    neighbors = defaultdict(set)

    # Transfer the streets from one-way to two-way
    while queue:
        junction = queue.pop(0)
        for neigh in connections[junction]:
            if level[junction] - level[neigh] < level[neigh] - 1:
                level[neigh] -= 1
                reachable_junctions[neigh] = junction
                neighbors[junction].add(neigh)
                if level[neigh] > 0:
                    queue.append(neigh)

    total_possibilities = junctions * (junctions - 1) // 2  # Pair of intersections
    increased_proposal = 0

    # Restoration the original two-way roads.
    for junction in reversed(range(1, junctions + 1)):
        for neigh in neighbors[junction]:
            total_possibilities += level[neigh]
        for neigh in connections[junction]:
            if connected := reachable_junctions.get(neigh):
                total_possibilities += level[connected]
                increased_proposal += level[connected] * level[neigh]

    return max(total_possibilities, increased_proposal)
