def diameter_of_tree(n, edges):
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    def dfs(node, parent, depth):
        nonlocal diameter
        current_depth = 0
        for child in adj_list[node]:
            if child != parent:
                current_depth += dfs(child, node, depth + 1)
        current_depth += 2  # Branching points: this node and itself
        if current_depth > diameter:
            diameter = current_depth

    diameter = 1  # Minimum distance is 1 for any node to itself
    dfs(1, -1, 0)
    return diameter

