from collections import defaultdict

def find(v, parents):
    return parents[v] if v != parents[v] else find(parents[v], parents)

def union(v, u, parents, size):
    rootv = find(v, parents)
    rootu = find(u, parents)
    if rootv == rootu:
        return
    if size[rootv] < size[rootu]:
        rootv, rootu = rootu, rootv
    parents[rootu] = rootv
    size[rootv] += size[rootu]

def manhatten_distance(parents, size, x, y):
    rootx = find(x, parents)
    rooty = find(y, parents)
    if rootx != rooty:
        return size[rootx]
    return abs(size[x] - size[y])

def greed_binary_string(parents, size, l):
    root = find(l, parents)
    while size[root] > 0 and size[root] < l:
        root = find(parents[root], parents)
    leng = [size, []]
    x = root
    while size[x] > 0:
        if size[x] < l:
            leng[1].append(0)
            x = parents[x]
        elif size[x] == l:
            leng[1].append(1)
            x = parents[x]
        else:
            leng[1].append(0)
            leng[0] += size[x]
            x = parents[x]
    return leng[0], max(0, leng[0]) - leng[0]

def main(n, q, roads, queries):
    parents = [i for i in range(n + 1)]
    size = [1] * (n + 1)
    for edge in roads:
        u, v, weight = edge
        if find(u, parents) != find(v, parents):
            union(u, v, parents, size)
    # Dump children for the scavenging
    for i in range(1, n + 1):
        parent = find(i, parents)
        if not i == parent:
            parents.pop(i)
            size.pop(i)
            children.append(parent)
    # Answer all sorted
    choices = [0 for _ in range(q + 1)]
    for edge in queries:
        v, u, l = edge
        choice = greed_binary_string(find(v, parents), size, l)
        choices[manhatten_distance(parents, size, u, v) + choice[1]] += 1
    for i in range(1, q + 1):
        if i != q + 1:
            res = sum([1 for x in range(q + 1) if x <= i]) + choices[i]
        else:
            res = sum([1 for x in range(q + 1) if x <= i])
        print(res)

