def find_max_path_weight(N, M, grid_weights):
    def allowed_paths(r1, c1, r2, c2):
        count = 0
        while r1 != r2 or c1 != c2:
            r1 -= 1
            r2 -= 1
            c1 -= 1
            c2 -= 1
            if r1 >= 0 and r1 < N and c1 >= 0 and c1 < N:
                count += grid_weights[r1][c1]
            if r2 >= 0 and r2 < N and c2 >= 0 and c2 < N:
                count += grid_weights[r2][c2]
        return count

    def depth_first_search(visited, row, col, count):
        if count >= N:
            return max(count, allowed_paths(row, col, (row, col)))
        max_val = allowed_paths(row, col, (row, col))
        for dx, dy in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
            if row + dx >= 0 and row + dx < N and col + dy >= 0 and col + dy < N:
                if (row + dx, col + dy) not in visited:
                    visited.add((row + dx, col + dy))
                    visited.add((row + dx, col + dy))
                    visited.add((row + dx, col + dy))
                    max_val = max(max_val, depth_first_search(visited, row + dx, col + dy, count + grid_weights[row + dx][col + dy]))
                    visited.remove((row + dx, col + dy))
                    visited.remove((row + dx, col + dy))
                    visited.remove((row + dx, col + dy))
        return max_val

    start_nodes = {}
    max_path = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                if grid_weights[i-1][j-1] == 0 and (k, i, j) not in start_nodes and allowed_paths(i, j, k, N):
                    start_nodes[(k, i, j)] = depth_first_search(set(), k, i, 0)

    for i in range(1, N + 1):
        for j in range(1, N + 1):
            start_nodes[(i, j, N)] = depth_first_search(set(), i, j, 0)

    for i in start_nodes:
        maximum = max(start_nodes[i], allowed_paths(i[1], i[2], (1, N), N))
        if maximum > max_path:
            max_path = maximum

    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                if grid_weights[i - 1][j - 1] == 0 and (k, j, i) in start_nodes and allowed_paths(i, j, k, N):
                    start_nodes[(k, j, i)] = max(start_nodes[(k, j, i)], depth_first_search(set(), k, j, 0) + 1)

    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                if grid_weights[k - 1][j-1] == 0 and ((i, j, k) in start_nodes) and allowed_paths((i, j, k), (1, N), (1, N), N) and (i, j, k) in start_nodes:
                    start_nodes[(i, j, k)] = max(start_nodes[(i, j, k)], start_nodes[(j, i, k)] + 1)

    return max_path

