from bisect import bisect_left, bisect_right

def find_left_bound(arr, x):
    i = bisect_left(arr, x)
    if i != len(arr) and arr[i] == x:
        return i
    else:
        return -1

def find_right_bound(arr, x):
    i = bisect_right(arr, x)
    if i != 0 and arr[i-1] == x:
        return i - 1
    else:
        return -1

def solve_test_case(arr_A, arr_B):
    N = len(arr_A)
    M = len(arr_B)

    # For each element in B, calculate the sum of rangeMin(B[i], B[j]) for all j >= i using prefix sums
    prefix_sum_B = [0 for _ in range(M + 1)]
    for j in range(1, M + 1):
        prefix_sum_B[j] = prefix_sum_B[j-1] + arr_B[j-1]

    answer = 0
    arr_B_set = sorted(set(arr_B))

    for i in range(M):
        left_bound_index = find_left_bound(arr_B_set, i)
        right_bound_index = find_right_bound(arr_B_set, i)

        min_value_sum = 0
        for j in range(i, M):
            min_value = arr_B_set[i]
            if left_bound_index is not -1 and j > left_bound_index:
                min_value = arr_B_set[left_bound_index]
            if right_bound_index is not -1 and j < right_bound_index:
                min_value = min(min_value, arr_B_set[right_bound_index])

            if i == j:
                min_value_sum += min_value * j
            else:
                min_value_sum += min_value * (prefix_sum_B[j+1] - prefix_sum_B[i])

        answer += min_value_sum

    return answer

def main():
    T = int(input())
    for _ in range(T):
        N, M = map(int, input().split())
        arr_A = list(map(int, input().split()))
        arr_B = list(map(int, input().split()))
        print(solve_test_case(arr_A, arr_B))

if __name__ == "__main__":
    main()
