def max_connected_component(n, k, grid):
    def dfs(r, c):
        if grid[r][c] == 'X':
            return 0
        grid[r][c] = 'X'  # Mark as visited by setting to 'X'
        size = 1
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == '.':
                size += dfs(nr, nc)
        return size

    max_size = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                component_size = dfs(i, j)
                if component_size > max_size:
                    max_size = component_size
    return max_size

