def is_doofish(N):
    """Check if a Doofish Matrix of order N exists."""
    return (2*N-1)**2 >= N**2

def print_doofish(N):
    """Print a valid Doofish Matrix of order N."""
    if not is_doofish(N):
        print("Boo")
    else:
        for _ in range(N):
            for j in range(1, 2*N):
                print(j, end=' ')
